//! Structural SQL input generated by the existing repository schema owner.

use super::{StoreError, StoreResult};
use serde::Deserialize;
use std::collections::HashSet;
use tokio_postgres::types::Type;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct StorageSchema {
    pub version: String,
    pub initialization: Vec<String>,
    pub(crate) permitted_unmarked: Vec<String>,
    pub(crate) received_value_owners: Vec<String>,
    pub(crate) tables: Vec<Table>,
    pub(crate) recall: RecallStatements,
    pub(crate) lexical: LexicalStatements,
    pub(crate) default_story: Box<serde_json::value::RawValue>,
}

/// Shared Source SQL in the operator's verified release, generated with
/// PostgreSQL's typed parameter markers for the stand-alone caller.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct RecallStatements {
    pub insert: String,
    pub reconcile: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct LexicalStatements {
    pub work: String,
    pub write: String,
    pub complete: String,
    pub remove_awareness: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct Table {
    pub name: String,
    pub columns: Vec<Column>,
    pub children: Vec<Child>,
    pub ordered_writes: bool,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct Column {
    pub name: String,
    pub data_type: SqlType,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct Child {
    pub field: String,
    pub table: String,
    pub order_by_identity: bool,
}

#[derive(Clone, Copy, Deserialize)]
pub(crate) enum SqlType {
    #[serde(rename = "TEXT")]
    Text,
    #[serde(rename = "BIGINT")]
    Integer,
    #[serde(rename = "DOUBLE PRECISION")]
    Double,
    #[serde(rename = "JSONB")]
    Json,
    #[serde(rename = "TEXT[]")]
    TextArray,
    #[serde(rename = "SMALLINT[]")]
    SmallIntegerArray,
}

impl SqlType {
    pub fn postgres(self) -> Type {
        match self {
            Self::Text => Type::TEXT,
            Self::Integer => Type::INT8,
            Self::Double => Type::FLOAT8,
            Self::Json => Type::JSONB,
            Self::TextArray => Type::TEXT_ARRAY,
            Self::SmallIntegerArray => Type::INT2_ARRAY,
        }
    }

    pub fn parameter(self) -> Type {
        match self {
            Self::Json => Type::TEXT,
            other => other.postgres(),
        }
    }
}

pub(crate) const FIXED_COLUMNS: [(&str, SqlType); 7] = [
    ("world_id", SqlType::Text),
    ("id", SqlType::Text),
    ("parent_id", SqlType::Text),
    ("slot", SqlType::Text),
    ("position", SqlType::Integer),
    ("revision", SqlType::Integer),
    ("payload", SqlType::Text),
];

fn identifier(value: &str) -> bool {
    value.len() <= 63
        && value.as_bytes().first().is_some_and(u8::is_ascii_lowercase)
        && value
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
}

impl StorageSchema {
    pub(crate) fn retained_bytes(&self) -> Option<usize> {
        use std::mem::size_of;
        let strings = |values: &Vec<String>| {
            values.iter().try_fold(
                values.capacity().checked_mul(size_of::<String>())?,
                |bytes, value| bytes.checked_add(value.capacity()),
            )
        };
        let mut bytes = size_of::<Self>().checked_add(self.version.capacity())?;
        bytes = bytes
            .checked_add(strings(&self.initialization)?)?
            .checked_add(strings(&self.permitted_unmarked)?)?
            .checked_add(strings(&self.received_value_owners)?)?
            .checked_add(self.recall.insert.capacity())?
            .checked_add(self.recall.reconcile.capacity())?
            .checked_add(self.default_story.get().len())?
            .checked_add(self.lexical.work.capacity())?
            .checked_add(self.lexical.write.capacity())?
            .checked_add(self.lexical.complete.capacity())?
            .checked_add(self.lexical.remove_awareness.capacity())?
            .checked_add(self.tables.capacity().checked_mul(size_of::<Table>())?)?;
        for table in &self.tables {
            bytes = bytes
                .checked_add(table.name.capacity())?
                .checked_add(table.columns.capacity().checked_mul(size_of::<Column>())?)?
                .checked_add(table.children.capacity().checked_mul(size_of::<Child>())?)?;
            for column in &table.columns {
                bytes = bytes.checked_add(column.name.capacity())?;
            }
            for child in &table.children {
                bytes = bytes
                    .checked_add(child.field.capacity())?
                    .checked_add(child.table.capacity())?;
            }
        }
        Some(bytes)
    }

    pub(crate) fn validate(&self) -> StoreResult<()> {
        if self.version.is_empty()
            || self.recall.insert.is_empty()
            || self.recall.reconcile.is_empty()
            || self.lexical.work.is_empty()
            || self.lexical.write.is_empty()
            || self.lexical.complete.is_empty()
            || self.lexical.remove_awareness.is_empty()
            || self
                .tables
                .first()
                .is_none_or(|table| table.name != "data_world")
        {
            return Err(StoreError::Schema);
        }
        let mut seen = HashSet::new();
        for table in self.tables.iter().rev() {
            let mut columns: HashSet<&str> = FIXED_COLUMNS.iter().map(|(name, _)| *name).collect();
            if !identifier(&table.name)
                || table
                    .children
                    .iter()
                    .any(|child| !seen.contains(child.table.as_str()))
                || !seen.insert(table.name.as_str())
                || table.columns.iter().any(|column| {
                    !identifier(&column.name) || !columns.insert(column.name.as_str())
                })
            {
                return Err(StoreError::Schema);
            }
        }
        if self
            .received_value_owners
            .iter()
            .any(|name| !seen.contains(name.as_str()))
            || self.received_value_owners.is_empty()
            || self
                .received_value_owners
                .iter()
                .collect::<HashSet<_>>()
                .len()
                != self.received_value_owners.len()
        {
            return Err(StoreError::Schema);
        }
        Ok(())
    }
}
